import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";

const scriptRoot = dirname(fileURLToPath(import.meta.url));
const repositoryRoot = join(scriptRoot, "../../..");
const outfile = join(
  repositoryRoot,
  "packages/codex-plugin/failure-report/mcp/server.mjs",
);
const check = process.argv.includes("--check");

const result = await build({
  absWorkingDir: repositoryRoot,
  entryPoints: ["packages/mcp-adapter/src/stdio.ts"],
  outfile,
  alias: {
    "@failure-report/protocol": join(
      repositoryRoot,
      "packages/protocol/src/index.ts",
    ),
  },
  banner: {
    js: "// Generated by pnpm build:codex-plugin. Do not edit.\n",
  },
  bundle: true,
  charset: "utf8",
  format: "esm",
  legalComments: "none",
  minify: true,
  platform: "node",
  target: "node24",
  write: false,
});

const output = result.outputFiles?.find((file) => file.path === outfile);
if (!output) {
  throw new Error("esbuild did not return the expected plugin MCP bundle");
}
const generated = Buffer.from(output.text.replace(/^[\t ]+$/gmu, ""));

if (check) {
  const committed = await readFile(outfile);
  if (!committed.equals(generated)) {
    throw new Error(
      "Codex plugin MCP bundle is stale; run `pnpm build:codex-plugin`.",
    );
  }
  console.log("codex_plugin_bundle=up_to_date");
} else {
  await writeFile(outfile, generated);
  console.log(`codex_plugin_bundle=${outfile}`);
}
